function constructMasterToC() {
    masterTocText = fs.readFileSync("./ct-genstat/master-toc-base.html").toString();

    let toInput = "";
    let keysSorted = Object.keys(individualTitleData);
    keysSorted.sort((a, b) => {
        if(!isNaN(a) && !isNaN(b)) {
            return Number(a) - Number(b);
        }
        let ra = a.replace(/[a-z]/gi, '');
        let rb = b.replace(/[a-z]/gi, '');

        if(!isNaN(ra) && !isNaN(rb)) {
            return Number(ra) - Number(rb);
        }

        if(Number(ra) == Number(rb)) {
            return parseInt(a.slice(-1), 36) - parseInt(b.slice(-1), 36);
        } else {
            return Number(a) - Number(b);
        }
    });
    
    keysSorted.forEach(chpNum => {
        let chp = individualTitleData[chpNum];
        toInput += `<p><a href="/title/${chpNum}">${chp.number.split(" ").map(w => w.substring(0, 1).toUpperCase() + w.substring(1).toLowerCase()).join(" ")}: ${chp.name.split(" ").map(w => w.substring(0, 1).toUpperCase() + w.substring(1).toLowerCase()).join(" ")}</a></p>\n`;
        // chp.chpNames.forEach(chpn => {
        //     toInput += `<p><a href="" class="indentLeft">${chpn}</a></p>`;
        // });
    });
    // for(var i = 0; i < allTitleData.names.length; i++) {
    //     toInput += `<p><a href="">${allTitleData.numbers[i]}: ${allTitleData.names[i]}</a></p>`
    // }

    masterTocText = masterTocText.replaceAll("<!-- %% REPLACE %% -->", toInput);
}

app.get("/title/:titlenum", (req, res) => {
    if(!individualTitleData[req.params.titlenum]) {
        res.status(404);
        res.send("Title not found.");
    }
    
    if(!renderedTitlePages[req.params.titlenum]) {
        let rendering = fs.readFileSync("./ct-genstat/chapter-base.html").toString();
        rendering = rendering.replaceAll("<!-- %% CHAPTER TITLE %% -->", `${individualTitleData[req.params.titlenum].number}: ${individualTitleData[req.params.titlenum].name}`);

        let linkData = "";
        for(var i = 0; i < individualTitleData[req.params.titlenum].chpNames.length; i++) {
            linkData += `<p><a href="/chapter/${individualTitleData[req.params.titlenum].chpNumbers[i].split(" ").pop()}">${individualTitleData[req.params.titlenum].chpNumbers[i]}: ${individualTitleData[req.params.titlenum].chpNames[i]}</a></p>`
        }
        if(individualTitleData[req.params.titlenum].chpNames.length == 0) {
            linkData = "<h2>All sections obsolete or repealed</h2>";
        }
        rendering = rendering.replaceAll("<!-- %% REPLACE WITH LAW %% -->", linkData);

        renderedTitlePages[req.params.titlenum] = rendering;
    }

    res.type("html");
    res.send(renderedTitlePages[req.params.titlenum]);
});

app.get("/chapter/chap_:chpnum.htm", (req, res) => {
    res.redirect(`/chapter/${req.params.chpnum}`);
});

app.get("/chapter/:chpnum", (req, res) => {
    req.params.chpnum = req.params.chpnum.replace(/^0+/, '');
    
    if(!chpData[req.params.chpnum.replace(/^0+/, '')]) {
        res.status(400);
        res.send("Invalid chapter number.");
        return;
    }

    let n = Number(req.params.chpnum.replace(/[a-z]/gi, ''));
    let fname = `./ct-genstat/processed/chap_${n < 100 ? "0" : ""}${n < 10 ? "0" : ""}${req.params.chpnum}.xml`

    if(!renderedChapterPages[req.params.chpnum]) {
        if(fs.existsSync(fname)) {
            console.log(`  Loading CT gen stat chapter ${req.params.chpnum}...`);

            let toSend = fs.readFileSync("./ct-genstat/chapter-base.html").toString();
            toSend = toSend.replaceAll("<!-- %% REPLACE WITH LAW %% -->", fs.readFileSync(fname).toString());
            // console.log(req);
            toSend = toSend.replaceAll("<!-- %% CHAPTER TITLE %% -->", `${chpData[req.params.chpnum].number}: ${chpData[req.params.chpnum].name}`);

            let heldTitle = "???";
            let heldTitleUrl = "";
            console.log(chpData[req.params.chpnum].name.split(" ").map(w => w.substring(0, 1).toUpperCase() + w.substring(1).toLowerCase()).join(" "));
            Object.keys(individualTitleData).forEach((titleName) => {
                if(heldTitle != "???") return;
                
                for(var i = 0; i < individualTitleData[titleName].chpNames.length; i++) {
                    if(individualTitleData[titleName].chpNames[i].toLowerCase() == chpData[req.params.chpnum].name.toLowerCase()) {
                        heldTitle = `${individualTitleData[titleName].number}`//: ${individualTitleData[titleName].name}`.split(" ").map(w => w.substring(0, 1).toUpperCase() + w.substring(1).toLowerCase()).join(" ");
                        heldTitleUrl = titleName;
                        break;
                    }
                }
            });
            toSend = toSend.replaceAll("<!-- %% TITLE NUMBER -->", heldTitle.split(" ").map(w => w.substring(0, 1).toUpperCase() + w.substring(1).toLowerCase()).join(" "));
            toSend = toSend.replaceAll("<!-- %% TITLE URL -->", heldTitleUrl);

            toSend = toSend.replaceAll("/* %% CHAPTER ONLY */", ".showOnlyInChapter {display: initial !important;}")

            renderedChapterPages[req.params.chpnum] = toSend;
        } else {
            res.status(404);
            res.send("Chapter not found.");
            return;
        }
    }

    res.type("html");
    res.send(renderedChapterPages[req.params.chpnum]);
});

module.exports.app = app;

